type Todo = { id: string; title: string; done: boolean };

export function TodoList({ items }: { items: Todo[] }) {
  if (items.length === 0) return <p>Пока пусто</p>;
  return (
    <ul>
      {items.map((t) => (
        <li key={t.id} className={t.done ? "done" : undefined}>
          {t.title}
        </li>
      ))}
    </ul>
  );
}
